function amendSnapshotDeclarations(queueText, handoffText) {
  const q = JSON.parse(queueText);
  const h = JSON.parse(handoffText);
  const matches = q.tasks.filter(t => t.id === 'TASK-20261027-29802f');
  if (matches.length !== 1) throw new Error('Snapshot task inventory drift');
  const t = matches[0];
  if (t.state !== 'queued' || t.archive.commit_sha !== null || t.archive.parent_sha !== null || Object.keys(t.archive.path_sha256).length) throw new Error('Snapshot is no longer prospective');
  if (JSON.stringify(h.handoff) !== JSON.stringify(t.handoff)) throw new Error('Standalone handoff differs from queue');
  const p = 'problems/nistseed-fixed-x-native-admission.md';
  if (t.write_scope.includes(p) || t.artifact_paths.includes(p)) throw new Error('Amendment already applied');
  t.write_scope.push(p);
  t.artifact_paths.push(p);
  t.archive.binding_mode = 'content_at_commit';
  t.handoff.objective = 'Archive the exact twelve implementation artifacts, the current linked fixed-x problem record and own precommit receipt in isolation before independent engineering review.';
  t.handoff.completion_gate[1] = 'Run alone and stage exactly the twelve source-task artifacts, problems/nistseed-fixed-x-native-admission.md and own receipt. Derive actual commit, parent and all fourteen path hashes from Git, verify through the native dispatcher, and push before reviewer dispatch.';
  t.handoff.completion_gate[2] = 'No scientific approval, source-result repair or unrelated artifact is included. Retain the prospective fourteen-path scope amendment and exact pre/post declaration identities in own receipt; preserve completed source-envelope archives at their original content_at_commit bindings.';
  t.handoff.write_scope.push(p);
  t.handoff.artifact_paths.push(p);
  t.handoff.deliverables.push(p);
  return {
    queueText: JSON.stringify(q, null, 2) + '\n',
    handoffText: JSON.stringify({handoff: t.handoff}, null, 2) + '\n'
  };
}
